def merge(intervals):
    if not intervals:
        return []
    # Sort a copy by start so the input list is not mutated.
    sorted_intervals = sorted(intervals, key=lambda iv: iv[0])
    merged = []
    for start, end in sorted_intervals:
        if merged and start <= merged[-1][1]:
            # Overlapping or touching (start == last end): extend the last interval.
            merged[-1][1] = max(merged[-1][1], end)
        else:
            # Start a new interval (copy, so output doesn't alias the input).
            merged.append([start, end])
    return merged
